{"query": "
-- Check: are there truly former employees who have NO active salary record?
SELECT 
  COUNT(DISTINCT employee_id) AS former_employees_no_active_salary
FROM employees.salary s
WHERE s.to_date <> '9999-01-01'
  AND s.employee_id NOT IN (
    SELECT employee_id FROM employees.salary WHERE to_date = '9999-01-01'
  );
"}

{"query": "
-- Check department_employee for truly former employees (no active dept assignment)
SELECT 
  COUNT(DISTINCT employee_id) AS former_dept_employees_no_active_assignment
FROM employees.department_employee de
WHERE de.to_date <> '9999-01-01'
  AND de.employee_id NOT IN (
    SELECT employee_id FROM employees.department_employee WHERE to_date = '9999-01-01'
  );
"}

